// Lưu mã xác nhận vào Firestore
export const saveVerificationCode = async (uid: string, code: string) => {
  const userDocRef = doc(firestore, "verificationCodes", uid); // Đường dẫn dến tài liệu
  await setDoc(userDocRef, { code, createAt: Date.now() }); // Lưu mã xác nhận
  console.log("verification code save successfully!");
};

// Lấy mã xác nhận từ Firestore
export const getVericationCode = async (
  uid: string
): Promise<string | null> => {
  const userDocRef = doc(firestore, "verificationCodes", uid); // Đường dẫn dến tài liệu
  const docSnap = await getDoc(userDocRef);

  if (docSnap.exists()) {
    const data = docSnap.data();
    return data.code; // Trả về mã xác nhận
  } else {
    console.log(" No verication code found for this user ");
    return null;
  }
};

//Hàm xác minh mã OTP:
export const verificationCode = async (
  uid: string,
  inputCode: string
): Promise<boolean> => {
  const userDoc = doc(firestore, "verificationCodes", uid); // Đường dẫn dến tài liệu
  const docSnapshot = await getDoc(userDoc);
  if (!docSnapshot.exists()) {
    throw new Error("Verification code not found.");
  }

  const { code, createdAt } = docSnapshot.data();
  const now = new Date();

  if (
    inputCode === code &&
    now.getTime() - createdAt.toDate().getTime() < 10 * 60 * 1000
  ) {
    return true;
  }

  throw new Error("Invalid or expired verification code.");
};

//Xóa mã xác nhận sau khi xác thực thành công
export const deleteVericationCode = async (uid: string) => {
  const userDocRef = doc(firestore, "verificationCodes", uid); // Đường dẫn dến tài liệu
  await deleteDoc(userDocRef);
  console.log("Verification code delete successfully .");
};

export const handleResendEmail = async () => {
  try {
    const userId = auth.currentUser?.uid;
    const email = auth.currentUser?.email;

    if (!userId || !email) {
      throw new Error("User not logged in.");
    }

    const newCode = generateVerificationCode();
    await saveVerificationCode(userId, newCode);
    await sendVerificationEmail(email, newCode);

    alert("Verification code resent to your email.");
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (error: any) {
    alert(error.message);
  }
};

