//  Tạo mã xác nhận
const generateVerificationCode = (): string => {
  const characters =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  let code = "";
  for (let i = 0; i < 6; i++) {
    code += characters.charAt(Math.floor(Math.random() * characters.length));
  }
  return code;
};
// Cập nhật mật khẩu thực (bước 2)---- đăng kí
export const updateUserPassword = async (newPassword: string) => {
  const currentUser = auth.currentUser;
  // Kiểm tra nếu currentUser tồn tại
  if (!currentUser) {
    throw new Error("User is not logged in . ");
  }

  // Kiểm tra nếu email không tồn tại
  if (!currentUser.email) {
    throw new Error("User email is not available.");
  }
  // Cập nhật Mật khẩu
  await updatePassword(currentUser, newPassword);
  // Tạo mã xác nhận
  const verificationCode = generateVerificationCode();
  await saveVerificationCode(currentUser.uid, verificationCode);
  await sendVerificationEmail(currentUser.email, verificationCode);
  console.log(" Password updated and verification email sent. ");
  return verificationCode;
};

//Hàm đăng nhập bằng email và mật khẩu
export const loginWithEmailAndPassword = async (
  email: string,
  password: string
) => {
  try {
    const userCredential = await signInWithEmailAndPassword(
      auth,
      email,
      password
    );
    const user = userCredential.user;
    return user;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (error: any) {
    console.error("Error during login ", error.message);
  }
};
// Hàm đăng nhập bằng Google
export const loginWithGoogle = async () => {
  try {
    const provider = new GoogleAuthProvider();
    const result = await signInWithPopup(auth, provider);
    const user = result.user;
    return user;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (error: any) {
    console.error("Error during Google login: ", error.message);
  }
};

//  Hàm lắng nghe trạng thái người dùng
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const monitorAuthState = (callback: (user: any) => void) => {
  return onAuthStateChanged(auth, callback);
};

//Hàm đăng xuất
export const logout = async () => {
  try {
    await signOut(auth);
    console.log("User logged out successfully.");
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
  } catch (error: any) {
    console.error("Error during logout:", error.message);
    throw error;
  }
};

export { auth, firestore, app };
